// Buzzer Alarm / Tune Player
// Plays a short melody once each time the button is pressed.

const int BUTTON_PIN = 2;
const int BUZZER_PIN = 8;

bool lastButtonReading = HIGH;

// A tiny melody: each pair is {note frequency in Hz, duration in ms}.
// 0 Hz = a rest (silence).
int melody[][2] = {
  {262, 200}, // C4
  {294, 200}, // D4
  {330, 200}, // E4
  {0,   100}, // rest
  {330, 200}, // E4
  {294, 200}, // D4
  {262, 400}, // C4 (held)
};
const int NOTE_COUNT = 7;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  bool currentReading = digitalRead(BUTTON_PIN);

  if (currentReading == LOW && lastButtonReading == HIGH) {
    playMelody();
  }

  lastButtonReading = currentReading;
}

void playMelody() {
  for (int i = 0; i < NOTE_COUNT; i++) {
    int frequency = melody[i][0];
    int duration = melody[i][1];

    if (frequency > 0) {
      tone(BUZZER_PIN, frequency, duration);
    } else {
      noTone(BUZZER_PIN);
    }
    delay(duration + 30); // small gap so consecutive notes are distinguishable
  }
  noTone(BUZZER_PIN);
}
